head.script:
// 전역변수 선언
scwin.SERVER_TIME = "";
scwin.USER_ID = "";
scwin.USER_NAME = "";
scwin.IS_ADMIN = "";
scwin.IS_CREATE = "";
scwin.IS_SYSTEMADMIN = "";
scwin.POPUP = "";


scwin.onpageload = function() {
    scwin.SERVER_TIME = $c.date.getServerDateTime("yyyy-MM-dd hh:mm:ss");
    serverTime.setValue(scwin.SERVER_TIME);
    scwin.USER_ID = WebSquare.cookie.getCookie("usrId");

    var requestData = {
        "elData": { "userId": scwin.USER_ID}
    }
    $c.sbm.execute(sbm_selectUsersMapping, requestData);

};

scwin.sbm_selectUsersMapping_submitdone = function (e) {
    var data  = e.responseJSON.elData.usersVoList;
    var header = e.responseJSON.userHeader;
    scwin.USER_ID = header.usrId;
    scwin.USER_NAME = header.userName;
    scwin.IS_ADMIN = header.isAdmin;
    scwin.IS_CREATE = header.isCreate;

    // 시스템 관리자 여부 (해당 프로젝트가 전혀 없으면 시스템 관리자)
    if (data == ""){
        scwin.IS_SYSTEMADMIN = 1
    }

    // SelectBox와 프로젝트명 Bind
    var projectNameData = data.map(item => ({
    pjtId: item.pjtId,
    pjtName: item.pjtName,
    grpId: item.grpId,
    grpName: item.grpName
    }));

    dlt_projectName.setJSON(projectNameData, false);

    selectBoxProjectName.setNodeSet("data:dlt_projectName", "pjtName", "pjtId")

    // TextBox에 그룹명 초기값 Bind
    textGrpName.setValue("");

    // TextBox와 사용자명 Bind
    if (scwin.IS_SYSTEMADMIN) {
        textName1.setValue("관리자");
    } else {
        var nameData = data[0].name;
        textName1.setValue(nameData);
    }

};

// 오른쪽 상단 아이콘 클릭 이벤트 (마이페이지, 로그아웃 버튼 있는 팝업창 표시)
scwin.accountImg_onclick = function (e) {

    // 팝업창 열린 상태에서 중복 클릭 방지
    if (scwin.POPUP) {
        return;
    }

    var screenWidth = window.innerWidth || document.documentElement.clientWidth;

    var domBtn = document.querySelector('[id$="accountImg"]'); // ID가 accountImg로 끝나는 요소
    var rect = domBtn.getBoundingClientRect();

    var popupWidth = 300;
    var popupHeight = 300;
    var paddingTop = 4;
    var rightMargin = 20;

    var options = {
        id: "popup1",
        type: "wframePopup",
        height: popupHeight + "px",
        width: popupWidth + "px",
        top: (rect.top + rect.height + window.scrollY + paddingTop) + "px",
        left: (screenWidth - popupWidth - rightMargin) + "px",
        resizable: false,
        modal: false,
        popupName: "계정 관리",
        closeAction: "scwin.closeAction",
        fixPosition: true
    };

    if (scwin.IS_SYSTEMADMIN){
        $p.openPopup("popup_header_admin.xml", options); // 관리자일 경우
        scwin.POPUP = 1;
    } else {
        options.height = popupHeight - 100 + "px";
        $p.openPopup("popup_header.xml", options); // 그 외 사용자일 경우
        scwin.POPUP = 1;
    }

};

// 팝업창 닫을 때 팝업 상태 초기화
scwin.closeAction = function(id, info) {

  scwin.POPUP = 0;
  return true;
};


scwin.selectBoxProjectName_onchange = function (info) {

    var selectedPjtId = info.newValue; // 변경된 프로젝트 id
    var grpId = dlt_projectName.getMatchedColumnData("pjtId", selectedPjtId, "grpId"); // pjtId로 데이터 리스트에서 그룹아이디 조회

    // TextBox와 선택한 프로젝트에 따른 그룹명 표시
    var grpName = dlt_projectName.getMatchedColumnData("pjtId", selectedPjtId, "grpName"); // pjtId로 데이터 리스트에서 그룹명 조회
    textGrpName.setValue(grpName);

    var parentScwin = $p.getParentWindow().scwin;

    // 부모의 onProjectChange 함수를 호출하여, 선택된 프로젝트 정보를 전달합니다.
    if (parentScwin && typeof parentScwin.onProjectChange === "function") {
        parentScwin.onProjectChange(selectedPjtId, grpId);
    }
};

/**
 * 사이드바 토글 버튼 클릭 이벤트
 */
scwin.btn_sidebarToggle_onclick = function(e) {
    // 1. 프로젝트 선택 컴포넌트에서 현재 선택된 값을 가져옵니다.
    var selectedPjtId = selectBoxProjectName.getValue();

    // 2. 선택된 프로젝트가 없으면 alert을 띄우고, 있으면 부모의 토글 함수를 호출합니다.
    if (!selectedPjtId || selectedPjtId === "") {
        alert("프로젝트를 먼저 선택해주세요.");
        return;
    }

    var parentScwin = $p.getParentWindow().scwin;
    if (parentScwin && typeof parentScwin.toggleSidebar === "function") {
        parentScwin.toggleSidebar();
    }
};
